CREATE TABLE IF NOT EXISTS `certificates` (`id` INT AUTO_INCREMENT PRIMARY KEY, `code` VARCHAR(16) NOT NULL UNIQUE, `user_id` INT NOT NULL, `challenge_id` INT NOT NULL, `score` INT NOT NULL DEFAULT 0, `issued_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT `fk_cert_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE, CONSTRAINT `fk_cert_ch` FOREIGN KEY (`challenge_id`) REFERENCES `incident_challenges` (`id`) ON DELETE CASCADE, INDEX idx_cert_user (`user_id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `product_feedback` (`id` INT AUTO_INCREMENT PRIMARY KEY, `user_id` INT NULL, `kind` VARCHAR(16) NOT NULL DEFAULT 'saran', `message` VARCHAR(1000) NOT NULL, `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT `fk_fb_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
